// ByteForge .bfng v1 reader/generator; Java 17+, no external dependencies.
import java.nio.file.*;import java.nio.charset.*;import java.util.*;
public final class ByteForge {
 record Edge(int[] ctx,int next,int count){}
 static void die(String s){System.err.println("byteforge: "+s);System.exit(1);}
 public static void main(String[] a)throws Exception{if(a.length<1||a.length>2)die("usage: java ByteForge model.bfng [token-count]");List<String> lines=Files.readAllLines(Path.of(a[0]),StandardCharsets.US_ASCII);if(lines.isEmpty())die("empty model");String[] h=lines.get(0).split("\\t",-1);if(h.length!=4||!h[0].equals("BYTEFORGE_NGRAM_V1"))die("bad model header");int order=Integer.parseInt(h[1]),vn=Integer.parseInt(h[2]),bos=Integer.parseInt(h[3]);if(order<1||order>8||vn<1||vn>20000||bos!=vn)die("invalid model header");String[] v=new String[vn];List<Edge> es=new ArrayList<>();for(int l=1;l<lines.size();l++){String[] p=lines.get(l).split("\\t",-1);if(p.length==3&&p[0].equals("v")){int id=Integer.parseInt(p[1]);if(id<0||id>=vn)die("vocabulary id out of range");v[id]=new String(HexFormat.of().parseHex(p[2]),StandardCharsets.UTF_8);}else if(p.length==order+3&&p[0].equals("n")){int[] c=new int[order];for(int i=0;i<order;i++){c[i]=Integer.parseInt(p[i+1]);if(c[i]<0||c[i]>bos)die("context id out of range");}int n=Integer.parseInt(p[order+1]),count=Integer.parseInt(p[order+2]);if(n<0||n>=vn||count<=0)die("bad transition");es.add(new Edge(c,n,count));}else die("unknown record");}for(String t:v)if(t==null)die("missing vocabulary token");int steps=a.length==2?Integer.parseInt(a[1]):20;if(steps<0||steps>10000)die("bad token count");int[] ctx=new int[order];Arrays.fill(ctx,bos);List<String> out=new ArrayList<>();for(int k=0;k<steps;k++){Edge best=null;for(Edge x:es)if(Arrays.equals(x.ctx,ctx)&&(best==null||x.count>best.count||(x.count==best.count&&x.next<best.next)))best=x;if(best==null)break;if(v[best.next].equals("__BYTEFORGE_EOS__"))break;out.add(v[best.next]);System.arraycopy(ctx,1,ctx,0,order-1);ctx[order-1]=best.next;}System.out.println(String.join(" ",out));}
}
